using System.Globalization;
using System.Windows.Data;

// Generated by AI. Edited.
namespace Tune.Helpers.ValueConverters
{
    /// <summary>
    /// 将秒数（double）转换为时间字符串，格式自动选择：
    /// - 若总秒数 >= 3600，显示 "hh:mm:ss"
    /// - 否则显示 "mm:ss"
    /// 支持双向绑定，ConvertBack 可解析 "hh:mm:ss" 或 "mm:ss" 格式。
    /// </summary>
    public class SecondsToTimeConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value == null)
                return "00:00";

            double totalSeconds;
            try
            {
                totalSeconds = System.Convert.ToDouble(value);
            }
            catch
            {
                return "00:00";
            }

            // 处理负值或 NaN
            if (double.IsNaN(totalSeconds) || totalSeconds < 0)
                totalSeconds = 0;

            var time = TimeSpan.FromSeconds(totalSeconds);

            // 根据总时长决定格式
            if (time.TotalHours >= 1)
                return $"{time.Hours:D2}:{time.Minutes:D2}:{time.Seconds:D2}";
            else
                return $"{time.Minutes:D2}:{time.Seconds:D2}";
        }

        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is string str)
            {
                str = str.Trim();
                if (string.IsNullOrEmpty(str))
                    return 0.0;

                // 尝试解析 "hh:mm:ss" 或 "mm:ss"
                var parts = str.Split(':');
                if (parts.Length == 2)
                {
                    // mm:ss
                    if (int.TryParse(parts[0], out int minutes) &&
                        int.TryParse(parts[1], out int seconds))
                    {
                        return TimeSpan.FromMinutes(minutes).TotalSeconds + seconds;
                    }
                }
                else if (parts.Length == 3)
                {
                    // hh:mm:ss
                    if (int.TryParse(parts[0], out int hours) &&
                        int.TryParse(parts[1], out int minutes) &&
                        int.TryParse(parts[2], out int seconds))
                    {
                        return TimeSpan.FromHours(hours).TotalSeconds +
                               TimeSpan.FromMinutes(minutes).TotalSeconds +
                               seconds;
                    }
                }
            }
            // 解析失败返回 0
            return 0.0;
        }
    }
}
